  @media (max-width:560px){
    :root{--header-h:64px}
    .logo{height:38px}
    .section{padding:52px 0}
    .hero{padding-top:calc(var(--header-h) + 32px)}
    .hero h1{font-size:clamp(1.65rem,7.6vw,2.2rem)}
    .tagline{font-size:1.05rem;margin:14px 0 24px}
    .h2,.session .h2,.final h2{font-size:clamp(1.55rem,6.8vw,1.9rem)}
    .xym .h2{font-size:clamp(1.8rem,8vw,2.1rem)}
    .lead{font-size:1rem}
    .meta{font-size:.9rem}
    .products{grid-template-columns:repeat(2,1fr);gap:12px}
    .hub{grid-template-columns:1fr}
    .leader-grid{grid-template-columns:repeat(2,1fr);gap:12px}
    .leader .info{padding:12px 14px 16px}
    .leader h3{font-size:.92rem;line-height:1.3}
    .leader p{font-size:.78rem}
    .team-card{padding:18px 12px;gap:12px}
    .team-card svg.users{width:44px;height:44px}
    .team-card h3{font-size:.88rem}
    .team-card .btn{padding:9px 12px;font-size:.78rem;gap:8px}
    .actions .btn{flex:1 1 100%}
    .badges{display:flex;width:max-content;max-width:100%}
    .badge{padding:8px 12px;font-size:.74rem}
    .cheers{position:static;width:52px;margin-bottom:14px}
    .cocktail .btn{align-self:stretch}
    .final-meta .meta{flex-direction:column;align-items:flex-start}
    .neon{left:5%;top:10%}
    .speaker{padding:14px 16px}
    .avatar{width:68px;height:68px}
  }
  @media (max-width:360px){
    .container,.session-copy{width:calc(100% - 28px)}
    .badge{padding:7px 9px;font-size:.66rem}
    .leader-grid{gap:10px}
    .team-card .btn svg{display:none}
  }
  @media (prefers-reduced-motion:reduce){
    *,*::before,*::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}
    .reveal{opacity:1;transform:none}
  }
</style>
</head>
