<main id="main">

  <!-- HERO -->
  <section class="hero" id="overview">
    <div class="hero-media" role="img" aria-label="Fontainebleau, Las Vegas at dusk with a neon sign reading See you in Las Vegas, Guidewire Connections 2026">
      <div class="neon" aria-hidden="true">
        <div class="script s1">See you in</div>
        <div class="script s2">Las Vegas</div>
        <div class="conf">GUIDEWIRE<br>CONNECTIONS 2026</div>
      </div>
    </div>
    <div class="container">
      <div class="hero-copy reveal">
        <p class="eyebrow">Guidewire Connections 2026</p>
        <div class="badges">
          <span class="badge badge-gold">Gold Plus Sponsor</span>
          <span class="badge badge-dark">Booth PS-G+1</span>
        </div>
        <h1>From Guidewire Core<br>to <span class="grad-cyan">Intelligent Insurance.</span></h1>
        <p class="tagline grad-cyan">Modernize. Connect. Orchestrate. Together.</p>
        <div class="meta">
          <span><svg class="ic-white"><use href="#i-cal"/></svg>October 26 – 29, 2026</span>
          <span><svg class="ic-white"><use href="#i-pin"/></svg>Fontainebleau, Las Vegas</span>
        </div>
        <div class="actions">
          <a href="#leaders" class="btn btn-primary">Book a Meeting <svg><use href="#i-arrow"/></svg></a>
          <a href="#insurance-in-a-box" class="btn btn-outline">Explore Our Capabilities</a>
        </div>
      </div>
    </div>
  </section>

  <!-- INSURANCE IN A BOX -->
  <section class="iiab section" id="insurance-in-a-box">
    <div class="container iiab-grid">
      <div class="reveal">
        <p class="eyebrow">Insurance-in-a-Box</p>
        <h2 class="h2">A Connected Way to<br>Modernize <span class="grad-text">Insurance.</span></h2>
        <p class="lead">One ecosystem to implement, modernize, automate and scale your insurance operations — from core to cloud to AI.</p>
        <a href="#guidewire" class="btn btn-primary">Explore Insurance-in-a-Box <svg><use href="#i-arrow"/></svg></a>
      </div>

      <div class="hub reveal">
        <div class="hub-col left">
          <div class="hub-card"><span class="ico"><svg><use href="#i-monitor"/></svg></span><h4>Core Insurance Operations</h4></div>
          <div class="hub-card"><span class="ico"><svg><use href="#i-cx"/></svg></span><h4>Digital Experiences</h4></div>
          <div class="hub-card"><span class="ico"><svg><use href="#i-brain-cloud"/></svg></span><h4>AI-Powered Workflows</h4></div>
        </div>
        <div class="cube" role="img" aria-label="Insurance-in-a-Box"><span>Insurance-<br>in-a-Box</span></div>
        <div class="hub-col right">
          <div class="hub-card"><span class="ico"><svg><use href="#i-cloud-up"/></svg></span><h4>Cloud Infrastructure</h4></div>
          <div class="hub-card"><span class="ico"><svg><use href="#i-lock"/></svg></span><h4>Cybersecurity</h4></div>
          <div class="hub-card"><span class="ico"><svg><use href="#i-people"/></svg></span><h4>Managed Services</h4></div>
        </div>
      </div>
    </div>
  </section>

  <!-- GUIDEWIRE -->
  <section class="core section" id="guidewire">
    <div class="container">
      <div class="reveal">
        <p class="eyebrow">Your Guidewire Investment.</p>
        <h2 class="h2">More Than a Core System.</h2>
        <p class="lead">Make it the engine of what's next.</p>
      </div>
      <div class="products reveal">
        <div class="product"><svg><use href="#i-doc"/></svg>PolicyCenter</div>
        <div class="product"><svg><use href="#i-db"/></svg>BillingCenter</div>
        <div class="product"><svg><use href="#i-shield"/></svg>ClaimCenter</div>
        <div class="product"><svg><use href="#i-cloud-up"/></svg>Guidewire Cloud</div>
        <div class="product"><svg><use href="#i-now"/></svg>InsuranceNow</div>
        <div class="product"><svg><use href="#i-brain"/></svg>AI + Guidewire</div>
      </div>
    </div>
  </section>

  <!-- XYMPHONY -->
  <section class="xym section on-dark" id="xymphony">
    <div class="xym-wave" aria-hidden="true"></div>
    <div class="container xym-grid">
      <div class="reveal">
        <h2 class="h2">Meet <span class="xym-logo" role="img" aria-label="Smart IMS Xymphony"></span></h2>
        <p class="sub">Agentic AI. Built for Insurance.</p>
        <p class="lead">Connect AI agents, enterprise data and workflows to create intelligent operations around your Guidewire core.</p>
        <a href="#event-highlights" class="btn btn-primary">See Xymphony in Action <svg><use href="#i-arrow"/></svg></a>
      </div>
      <div class="features reveal">
        <div class="feature"><div class="ring"><svg><use href="#i-uw"/></svg></div><h4>Underwriting</h4><p>Intelligent<br>submissions</p></div>
        <div class="feature"><div class="ring"><svg><use href="#i-claims"/></svg></div><h4>Claims</h4><p>Automated<br>triage &amp; routing</p></div>
        <div class="feature"><div class="ring"><svg><use href="#i-policy"/></svg></div><h4>Policy Servicing</h4><p>Proactive<br>operations</p></div>
        <div class="feature"><div class="ring"><svg><use href="#i-agent"/></svg></div><h4>Customer Experience</h4><p>Instant answers</p></div>
      </div>
    </div>
  </section>

  <!-- FEATURED SESSION -->
  <section class="session section" id="event-highlights">
    <div class="session-media" role="img" aria-label="Keynote speaker on stage at Guidewire Connections 2026">
      <div class="stage-label">GUIDEWIRE<br>CONNECTIONS 2026</div>
    </div>
    <div class="container session-grid">
      <div class="session-copy reveal">
        <p class="eyebrow">Featured Session</p>
        <h2 class="h2">Intelligent Operations <span class="line2 grad-text">with Guidewire InsuranceNow + AI</span></h2>
        <span class="pill">45-MINUTE PANEL</span>
        <p class="lead">Explore how carriers can use AI and agentic workflow patterns to create intelligent operations across underwriting, claims, servicing, billing and IT — extending the value of Guidewire across the enterprise.</p>
        <div class="meta">
          <span><svg class="ic-blue"><use href="#i-cal"/></svg><span class="two"><span>Wednesday, October 28</span><span>2:15 – 3:00 PM</span></span></span>
          <span><svg class="ic-violet"><use href="#i-pin"/></svg>Fontainebleau, Las Vegas</span>
        </div>
        <button type="button" class="btn btn-primary" id="addAgenda">Add to My Agenda <svg><use href="#i-arrow"/></svg></button>
      </div>

      <div class="speakers reveal">
        <div class="speaker">
          <div class="avatar photo-avatar" role="img" aria-label="Vinod Padimary" style="--photo:var(--img-team-vinod)"></div>
          <div>
            <span class="tag">SPEAKER</span>
            <h4>Vinod Padimary</h4>
            <p>Technology Leader<br>Insurance<br>Smart IMS</p>
          </div>
        </div>
        <div class="speaker">
          <div class="avatar"><svg viewBox="0 0 100 100"><use href="#i-person"/></svg></div>
          <div>
            <div class="small-cap">In conversation with</div>
            <h4>George Giavas</h4>
          </div>
        </div>
      </div>
    </div>
  </section>

  <!-- COCKTAIL -->
  <section class="cocktail on-dark" id="cocktail">
    <div class="cocktail-grid">
      <div class="cocktail-media" role="img" aria-label="Champagne glasses, flowers and a golden lamp on a candle-lit table"></div>
      <div class="cocktail-body reveal">
        <svg class="cheers" viewBox="0 0 64 64" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
          <g transform="rotate(-16 22 30)"><path d="M14 14h14l-1.2 13a5.8 5.8 0 0 1-11.6 0z"/><path d="M15 21h12"/><path d="M21 33v17M15 51h12"/></g>
          <g transform="rotate(16 42 30)"><path d="M36 14h14l-1.2 13a5.8 5.8 0 0 1-11.6 0z"/><path d="M37 21h12"/><path d="M43 33v17M37 51h12"/></g>
          <path d="M32 4v5M26 6l2.5 4M38 6l-2.5 4"/>
        </svg>
        <p class="eyebrow">Sponsored Event</p>
        <h2 class="h2">Welcome Cocktail to <span class="line2 grad-text">InsuranceNow</span></h2>
        <p class="sub">Let's continue the conversations.</p>
        <p class="lead">Join us for an evening of great conversations, connections and new possibilities at our sponsored welcome cocktail for InsuranceNow.</p>
        <div class="meta">
          <span><svg class="ic-white"><use href="#i-cal"/></svg>October 26 – 29, 2026</span>
          <span><svg class="ic-white"><use href="#i-pin"/></svg>Fontainebleau, Las Vegas</span>
        </div>
        <a href="#leaders" class="btn btn-primary">Stay Tuned for Details <svg><use href="#i-arrow"/></svg></a>
      </div>
    </div>
  </section>

  <!-- LEADERS -->
  <section class="leaders section" id="leaders">
    <div class="container">
      <div class="reveal">
        <p class="eyebrow">Meet Our Leaders</p>
        <h2 class="h2">Connect With Our Insurance Leaders.</h2>
        <p class="lead">Bring your challenges. Explore ideas. Discuss what's next.</p>
      </div>
      <div class="leader-grid reveal">
        <article class="leader">
          <div class="photo" role="img" aria-label="Shyam Vellala" style="--photo:var(--img-team-shyam)"></div>
          <div class="info"><h3>Shyam Vellala</h3><p>Practice Leader<br>Insurance</p></div>
        </article>
        <article class="leader">
          <div class="photo" role="img" aria-label="Vinod Padimary" style="--photo:var(--img-team-vinod)"></div>
          <div class="info"><h3>Vinod Padimary</h3><p>Technology Leader<br>Insurance</p></div>
        </article>
        <article class="leader">
          <div class="photo" role="img" aria-label="Debadutta Nayak" style="--photo:var(--img-team-debadutta)"></div>
          <div class="info"><h3>Debadutta Nayak</h3><p>Leader – Growth &amp;<br>Partnership</p></div>
        </article>
        <article class="leader">
          <div class="photo" role="img" aria-label="Danielle Mathew" style="--photo:var(--img-team-danielle)"></div>
          <div class="info"><h3>Danielle Mathew</h3><p>Account<br>Coordinator</p></div>
        </article>
        <article class="leader">
          <div class="photo" role="img" aria-label="Austin Miller" style="--photo:var(--img-team-austin)"></div>
          <div class="info"><h3>Austin Miller</h3><p>Client Solutions<br>Manager</p></div>
        </article>
        <div class="team-card">
          <svg class="users"><use href="#i-users"/></svg>
          <h3>Meet More of Our Team<br>at Booth PS-G+1</h3>
          <a href="#contact" class="btn btn-primary btn-sm">Book a Meeting <svg><use href="#i-arrow"/></svg></a>
        </div>
      </div>
    </div>
  </section>

  <!-- FINAL CTA -->
  <section class="final on-dark" id="contact">
    <div class="container">
      <div class="reveal">
        <h2>Come for the Conversations.<br>Stay for the Possibilities.</h2>
        <p class="lead">Let's build what's next for insurance. Together.</p>
        <a href="#leaders" class="btn btn-primary">Meet Us at Booth PS-G+1 <svg><use href="#i-arrow"/></svg></a>
      </div>
      <div class="final-meta">
        <div class="meta">
          <span><svg class="ic-white"><use href="#i-cal"/></svg>October 26 – 29, 2026</span>
          <span><svg class="ic-white"><use href="#i-pin"/></svg>Fontainebleau, Las Vegas</span>
          <span><svg class="ic-white"><use href="#i-star"/></svg><span class="two"><span>Gold Plus Sponsor</span><span>Booth PS-G+1</span></span></span>
        </div>
      </div>
    </div>
  </section>
</main>

<script>
(() => {
  const header = document.querySelector('.site-header');
  const toggle = document.getElementById('navToggle');
  const links = document.getElementById('navLinks');
  const useEl = toggle.querySelector('use');

  const setMenu = open => {
    links.classList.toggle('open', open);
    toggle.setAttribute('aria-expanded', open);
    toggle.setAttribute('aria-label', open ? 'Close menu' : 'Open menu');
    useEl.setAttribute('href', open ? '#i-close' : '#i-menu');
  };
  toggle.addEventListener('click', () => setMenu(!links.classList.contains('open')));
  links.addEventListener('click', e => { if (e.target.closest('a')) setMenu(false); });
  document.addEventListener('keydown', e => { if (e.key === 'Escape') setMenu(false); });

  const onScroll = () => header.classList.toggle('scrolled', window.scrollY > 20);
  onScroll();
  window.addEventListener('scroll', onScroll, { passive: true });

  const navMap = new Map([...links.querySelectorAll('a')].map(a => [a.getAttribute('href').slice(1), a]));
  const spy = new IntersectionObserver(entries => {
    entries.forEach(entry => {
      if (!entry.isIntersecting) return;
      const link = navMap.get(entry.target.id);
      if (!link) return;
      navMap.forEach(a => a.classList.remove('active'));
      link.classList.add('active');
    });
  }, { rootMargin: '-45% 0px -50% 0px' });
  navMap.forEach((_, id) => { const el = document.getElementById(id); if (el) spy.observe(el); });

  const reveal = new IntersectionObserver(entries => {
    entries.forEach(entry => {
      if (entry.isIntersecting) { entry.target.classList.add('in'); reveal.unobserve(entry.target); }
    });
  }, { threshold: 0.12 });
  document.querySelectorAll('.reveal').forEach(el => reveal.observe(el));

  document.getElementById('addAgenda').addEventListener('click', () => {
    const ics = [
      'BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//Smart IMS//Guidewire Connections 2026//EN',
      'BEGIN:VEVENT',
      'UID:smartims-gwc2026-insurancenow-ai@smartims',
      'DTSTAMP:20261001T000000Z',
      'DTSTART:20261028T211500Z',
      'DTEND:20261028T220000Z',
      'SUMMARY:Intelligent Operations with Guidewire InsuranceNow + AI',
      'DESCRIPTION:45-minute panel with Vinod Padimary (Smart IMS) in conversation with George Giavas.',
      'LOCATION:Fontainebleau\\, Las Vegas',
      'END:VEVENT', 'END:VCALENDAR'
    ].join('\r\n');
    const url = URL.createObjectURL(new Blob([ics], { type: 'text/calendar' }));
    const a = Object.assign(document.createElement('a'), { href: url, download: 'smartims-gwc2026-session.ics' });
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  });
})();
</script>
